// We use the Verus standard library for Vec and proof constructs.
use vstd::prelude::*;
verus! {

    /// Given a vector `m` of `f32` values, returns a new vector whose elements
    /// are `m` in reverse order.
    #[verifier(publish)]
    pub fn numpy_flip(m: Vec<f32>) -> Vec<f32>
        // Postcondition: result has the same length as `m`, and for each valid
        // index `i`, result[i] == m[m.len() - 1 - i].
        ensures
            |result: &Vec<f32>|
                result.len() == m.len() &&
                forall(|i: usize| i < m.len() ==> result[i] == m[m.len() - 1 - i])
    {
        let n = m.len();
        let mut result: Vec<f32> = Vec::new();
        let mut i: usize = 0;

        // We'll build up `result` one element at a time, maintaining these invariants:
        // 1) 0 <= i <= n
        // 2) result.len() == i
        // 3) for all j < i, result[j] == m[n - 1 - j]
        // We also give a decreases clause on (n - i) to prove termination.
        while i < n
            invariant 0 <= i && i <= n
            invariant result.len() == i
            invariant forall(|j: usize| j < i ==> result[j] == m[n - 1 - j])
            decreases n - i
        {
            // Because i < n, we know (n - 1 - i) < n, so indexing is safe.
            assert(n - 1 - i < n);
            let x = m[n - 1 - i];
            result.push(x);
            i += 1;
        }

        result
    }
}